// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.Arrays;

import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.junit.jupiter.api.Test;

/**
 * Contract tests for query-local Frontier evidence in the packed planner.
 *
 * <p>
 * These tests deliberately use reflection until the session API exists. That keeps the first TDD failure in Surefire,
 * rather than stopping at test compilation, while still pinning the intended public and hot-path shapes.
 */
class PackedFrontierSessionContractTest {

	private static final String PACKED_COST_SESSION = PackedCostModel.class.getPackageName() + ".PackedCostSession";

	@Test
	void costModelRemainsFunctionalAndOpensAnAutoCloseableQuerySession() throws Exception {
		assertNotNull(PackedCostModel.class.getAnnotation(FunctionalInterface.class));
		assertEquals(1L, Arrays.stream(PackedCostModel.class.getMethods())
				.filter(method -> Modifier.isAbstract(method.getModifiers()))
				.count(), "PackedCostModel must remain a single-abstract-method lambda target");

		Class<?> sessionType = requiredClass(PACKED_COST_SESSION);
		assertTrue(sessionType.isInterface(), "PackedCostSession is a provider extension point");
		assertTrue(AutoCloseable.class.isAssignableFrom(sessionType),
				"Every cold planning session must close on success or failure");

		Method openSession = requiredMethod(PackedCostModel.class, "openSession", PackedQueryView.class);
		assertTrue(openSession.isDefault(), "Legacy PackedCostModel lambdas require a default scalar adapter");
		assertEquals(sessionType, openSession.getReturnType());
	}

	@Test
	void defaultScalarSessionDelegatesEveryEstimationPhaseToTheLegacyModel() throws Exception {
		int[] calls = new int[2];
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return 7.0d;
			}

			@Override
			public void estimate(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				calls[0]++;
				output.setRows(relationId, relationId + 1.0d);
			}

			@Override
			public void refineOperator(PackedQueryView query, int relationId, PackedCostContext context,
					PackedCostEstimate output) {
				calls[1]++;
				output.setRows(relationId + 2.0d, relationId + 3.0d);
			}
		};
		PackedQuery query = PackedQueryCodec.encode(new SingletonSet());
		PackedQueryView queryView = new PackedQueryView(query);
		Class<?> sessionType = requiredClass(PACKED_COST_SESSION);
		Object session = requiredMethod(PackedCostModel.class, "openSession", PackedQueryView.class)
				.invoke(model, queryView);
		assertTrue(sessionType.isInstance(session));

		Method estimateLeaf = requiredMethod(sessionType, "estimateLeaf", int.class, PackedCostContext.class,
				PackedCostEstimate.class);
		Method appendFactor = requiredMethod(sessionType, "appendFactor", int.class, PackedCostContext.class,
				PackedCostEstimate.class);
		Method refineOperator = requiredMethod(sessionType, "refineOperator", int.class, PackedCostContext.class,
				PackedCostEstimate.class);
		PackedCostContext context = new PackedCostContext();
		PackedCostEstimate output = new PackedCostEstimate();

		estimateLeaf.invoke(session, 11, context, output);
		assertEquals(11.0d, output.outputRows());
		appendFactor.invoke(session, 13, context, output);
		assertEquals(13.0d, output.outputRows());
		refineOperator.invoke(session, 17, context, output);
		assertEquals(19.0d, output.outputRows());
		assertEquals(2, calls[0]);
		assertEquals(1, calls[1]);

		((AutoCloseable) session).close();
	}

	@Test
	void reusableCostSlotsCarryOnlyPrimitiveQueryLocalStateIdsAndResetToZero() throws Exception {
		Method estimateSetter = requiredMethod(PackedCostEstimate.class, "setEvidenceStateId", int.class);
		Method estimateGetter = requiredMethod(PackedCostEstimate.class, "evidenceStateId");
		assertEquals(int.class, estimateGetter.getReturnType());

		PackedCostEstimate estimate = new PackedCostEstimate();
		estimateSetter.invoke(estimate, 37);
		assertEquals(37, estimateGetter.invoke(estimate));
		estimate.clear();
		assertEquals(0, estimateGetter.invoke(estimate), "clear() must prevent state leakage between candidates");

		Method contextSetter = requiredDeclaredMethod(PackedCostContext.class, "setEvidenceStateId", int.class);
		Method contextGetter = requiredMethod(PackedCostContext.class, "evidenceStateId");
		assertEquals(int.class, contextGetter.getReturnType());

		PackedCostContext context = new PackedCostContext();
		contextSetter.invoke(context, 19);
		assertEquals(19, contextGetter.invoke(context));
		context.reset(new int[] { 1, 2 }, 0, 2, 11.0d);
		assertEquals(0, contextGetter.invoke(context), "reset() must detach a reused context from its old prefix");

		assertPrimitiveStateColumn(PackedCostEstimate.class);
		assertPrimitiveStateColumn(PackedCostContext.class);
	}

	@Test
	void sparseSubsetStateKeepsEvidenceIdAlignedAcrossReplacementAndGrowth() throws Exception {
		Method offer = requiredDeclaredMethod(PackedLongSubsetTable.class, "offer", long.class, double.class,
				double.class, double.class, int.class, int.class, int.class, int.class, long.class);
		Method evidenceStateId = requiredDeclaredMethod(PackedLongSubsetTable.class, "evidenceStateId", int.class);
		PackedLongSubsetTable table = new PackedLongSubsetTable(1);

		int state = (int) offer.invoke(table, 0b11L, 12.0d, 20.0d, 3.0d, 101, 1, 1, 1, 0b1100L);
		offer.invoke(table, 0b11L, 24.0d, 30.0d, 6.0d, 202, 2, 2, 2, 0b1110L);
		assertEquals(101, evidenceStateId.invoke(table, state),
				"A losing physical path must not overwrite the winning path's aligned evidence");

		offer.invoke(table, 0b11L, 8.0d, 10.0d, 2.0d, 303, 0, 3, 3, 0b1111L);
		assertEquals(303, evidenceStateId.invoke(table, state),
				"A lower-cost replacement must publish its matching query-local evidence state");

		for (int ordinal = 2; ordinal < 40; ordinal++) {
			long mask = 1L << ordinal;
			offer.invoke(table, mask, ordinal, ordinal, ordinal + 0.5d, 1_000 + ordinal, 0, 0, ordinal, mask);
		}
		for (int ordinal = 2; ordinal < 40; ordinal++) {
			int grownState = table.find(1L << ordinal);
			assertEquals(1_000 + ordinal, evidenceStateId.invoke(table, grownState),
					"Growing the sparse table must keep every primitive column aligned");
		}
	}

	@Test
	void detachedRecipesAndStoreWideCacheContainNoQueryLocalFrontierHandles() {
		assertNoQueryLocalFrontierFields(PackedPlanRecipe.class);
		assertNoQueryLocalFrontierFields(PackedPlanCache.class);
		assertNoQueryLocalFrontierFields(PackedPlanCache.Context.class);
		assertNoQueryLocalFrontierFields(PackedPlanCache.PlanEntry.class);
		assertNoQueryLocalFrontierFields(PackedPlanCache.QueryEntry.class);
	}

	private static Class<?> requiredClass(String name) {
		try {
			return Class.forName(name);
		} catch (ClassNotFoundException exception) {
			return fail("Missing theorem-safe packed session type " + name, exception);
		}
	}

	private static Method requiredMethod(Class<?> owner, String name, Class<?>... parameterTypes) {
		try {
			return owner.getMethod(name, parameterTypes);
		} catch (NoSuchMethodException exception) {
			return fail("Missing packed Frontier contract " + owner.getSimpleName() + "." + name, exception);
		}
	}

	private static Method requiredDeclaredMethod(Class<?> owner, String name, Class<?>... parameterTypes) {
		try {
			Method method = owner.getDeclaredMethod(name, parameterTypes);
			method.setAccessible(true);
			return method;
		} catch (NoSuchMethodException exception) {
			return fail("Missing packed Frontier hot-path contract " + owner.getSimpleName() + "." + name,
					exception);
		}
	}

	private static void assertPrimitiveStateColumn(Class<?> owner) {
		Field field = Arrays.stream(owner.getDeclaredFields())
				.filter(candidate -> candidate.getName().equals("evidenceStateId"))
				.findFirst()
				.orElseGet(() -> fail(owner.getSimpleName() + " must retain an aligned evidenceStateId column"));
		assertEquals(int.class, field.getType(), "Packed state references must remain allocation-free primitive IDs");
	}

	private static void assertNoQueryLocalFrontierFields(Class<?> owner) {
		for (Field field : owner.getDeclaredFields()) {
			String normalizedName = field.getName().replace("_", "").toLowerCase();
			String typeName = field.getType().getSimpleName();
			assertFalse(normalizedName.contains("evidencestate"),
					() -> owner.getSimpleName() + "." + field.getName() + " leaks a query-local evidence ID");
			assertFalse(typeName.equals("PackedCostSession")
					|| typeName.equals("EvidenceStateRef")
					|| typeName.equals("FrontierStateArena"),
					() -> owner.getSimpleName() + "." + field.getName() + " leaks " + typeName);
		}
	}
}
